package com.ridex.location.config;
import com.ridex.location.dto.AuthenticatedUser; import com.ridex.location.exception.InvalidCredentialsException; import org.junit.jupiter.api.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
class SecurityUtilsTest { @AfterEach void clear(){SecurityContextHolder.clearContext();} @Test void returnsAuthenticatedUserId(){UUID id=UUID.randomUUID();SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new AuthenticatedUser(id,"DRIVER"),null));assertEquals(id,SecurityUtils.getCurrentUserId());} @Test void rejectsMissingAuthentication(){assertThrows(InvalidCredentialsException.class,SecurityUtils::getCurrentUserId);} @Test void rejectsWrongPrincipal(){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("user",null));assertThrows(InvalidCredentialsException.class,SecurityUtils::getCurrentUserId);} }
